package com.nivor.habit;
import com.nivor.habit.dto.*;import jakarta.validation.Valid;import java.time.LocalDate;import java.util.*;import org.springframework.http.*;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.security.core.userdetails.UserDetails;import org.springframework.web.bind.annotation.*;
@RestController@RequestMapping("/api/habits")public class HabitController{
private final HabitService service;public HabitController(HabitService s){service=s;}
@GetMapping public List<HabitResponse> list(@AuthenticationPrincipal UserDetails u){return service.list(u.getUsername()).stream().map(HabitResponse::from).toList();}@GetMapping("/{id}")public HabitResponse get(@AuthenticationPrincipal UserDetails u,@PathVariable Long id){return HabitResponse.from(service.get(u.getUsername(),id));}@PostMapping public ResponseEntity<HabitResponse> create(@AuthenticationPrincipal UserDetails u,@Valid@RequestBody HabitRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(HabitResponse.from(service.create(u.getUsername(),r)));}@PutMapping("/{id}")public HabitResponse update(@AuthenticationPrincipal UserDetails u,@PathVariable Long id,@Valid@RequestBody HabitRequest r){return HabitResponse.from(service.update(u.getUsername(),id,r));}@DeleteMapping("/{id}")public ResponseEntity<Void> delete(@AuthenticationPrincipal UserDetails u,@PathVariable Long id){service.delete(u.getUsername(),id);return ResponseEntity.noContent().build();}
@PostMapping("/{id}/logs")public ResponseEntity<HabitLogResponse> log(@AuthenticationPrincipal UserDetails u,@PathVariable Long id,@Valid@RequestBody HabitLogRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(HabitLogResponse.from(service.log(u.getUsername(),id,r)));}@GetMapping("/{id}/logs")public List<HabitLogResponse> logs(@AuthenticationPrincipal UserDetails u,@PathVariable Long id){return service.logs(u.getUsername(),id).stream().map(HabitLogResponse::from).toList();}@PatchMapping("/{id}/logs/{date}")public HabitLogResponse setLog(@AuthenticationPrincipal UserDetails u,@PathVariable Long id,@PathVariable LocalDate date,@RequestBody LogUpdate r){return HabitLogResponse.from(service.setLog(u.getUsername(),id,date,r.completed()));}public record LogUpdate(boolean completed){}
}
